    "desc": "\uACE0\uC555 \uBB3C\uC904\uAE30\uAC00 \uC911\uB825\uC5D0 \uD718\uBA70 \uAC00\uB298\uC5B4\uC9C0\uACE0 \uD45C\uBA74\uC7A5\uB825\uC73C\uB85C \uC798\uB85D\uD574\uC838 \uB465\uADFC \uBC29\uC6B8\uB85C \uAC08\uB77C\uC9C4\uB2E4. \uC881\uC740 \uBC18\uC0AC\uAD11\uC774 \uC816\uC740 \uD45C\uBA74\uC744 \uB4DC\uB7EC\uB0B4\uACE0, \uB4DC\uBB38 \uBB3C\uBCF4\uB77C\uAC00 \uACE1\uC120\uC744 \uADF8\uB9AC\uBA70 \uB5A8\uC5B4\uC9C4\uB2E4."
