    "desc": "\uBC14\uC704 \uB3CC\uCD9C\uBD80\uC758 \uAC08\uB77C\uC9C4 \uD2C8\uC5D0\uC11C \uAC15\uBB3C\uC774 \uC3DF\uC544\uC9C4\uB2E4. \uD558\uC597\uAC8C \uB9D0\uB9B0 \uBB3C\uACB0 \uC544\uB798 \uAE4A\uC740 \uBB3C\uB9C9\uC774 \uC5EC\uB7EC \uAC08\uB798\uB85C \uAC08\uB77C\uC9C0\uACE0, \uAC80\uC740 \uC5F0\uBABB \uC704\uB85C \uAC70\uD488\uACFC \uBB3C\uBCF4\uB77C, \uB5A0\uB2E4\uB2C8\uB294 \uC548\uAC1C\uC640 \uD30C\uBB38\uC774 \uD37C\uC9C4\uB2E4."
