    "desc": "\uC5B4\uB450\uC6B4 \uBC1B\uCE68\uB300 \uC704\uC758 \uC720\uB9AC \uAD6C\uCCB4\uC785\uB2C8\uB2E4. \uD50C\uB77C\uC2A4\uB9C8 \uC904\uAE30\uAC00 \uC911\uC2EC\uC5D0\uC11C \uC720\uB9AC\uAE4C\uC9C0 \uC6C0\uC9C1\uC774\uBA70 \uB2FF\uB294 \uACF3\uC5D0\uC11C \uBC1D\uAC8C \uBD80\uCC44\uAF34\uB85C \uD37C\uC9C0\uACE0, \uBC1B\uCE68\uB300\uC640 \uBC14\uB2E5\uC744 \uBE44\uCDA5\uB2C8\uB2E4."
