    "desc": "\uC6D0\uBC18 \uBAA8\uC591\uC758 \uC804\uD558\uAC00 \uC9F8\uAE4D\uAC70\uB9AC\uB2E4 \uD558\uC597\uAC8C \uD130\uC9C0\uACE0, \uD45C\uBA74\uC5D0 \uC804\uAE30 \uC544\uD06C\uAC00 \uD750\uB974\uB294 \uC8FC\uC0AC\uC120 \uAC70\uD488\uC774 \uBD80\uD480\uC5B4 \uC624\uB985\uB2C8\uB2E4. \uAC70\uD488\uC740 \uC810\uBA78\uD558\uACE0 \uCC22\uC5B4\uC9C0\uB2E4 \uD569\uC120\uB418\uC5B4 \uAEBC\uC9C4 \uD53D\uC140\uC744 \uD769\uBFCC\uB9BD\uB2C8\uB2E4."
