    "desc": "\uBC14\uB2E5 \uD22C\uC0AC\uAE30\uAC00 \uD68C\uC804\uD558\uB294 \uC640\uC774\uC5B4\uD504\uB808\uC784 \uBAA8\uD615\uC744 \uBE5B\uC758 \uC6D0\uBFD4 \uC548\uC5D0 \uBE44\uCDA5\uB2C8\uB2E4. \uC8FC\uC0AC\uC120\uC774 \uD750\uB974\uACE0 \uB370\uC774\uD130 \uACE0\uB9AC\uAC00 \uC8FC\uC704\uB97C \uB3CC\uBA70 \uC601\uC0C1\uC774 \uAE5C\uBE61\uC774\uACE0 \uCC22\uC5B4\uC9C0\uBA70 \uD754\uB4E4\uB9BD\uB2C8\uB2E4."
