    "desc": "\uC601\uC6C5 \uC8FC\uC704\uC5D0 \uC870\uC900 \uAD04\uD638\uAC00 \uACE0\uC815\uB418\uACE0 \uC8FC\uC0AC\uC120\uC774 \uBA38\uB9AC\uBD80\uD130 \uBC1C\uB05D\uAE4C\uC9C0 \uD6D1\uC73C\uBA70 \uC11C\uC11C\uD788 \uC2DD\uB294 \uC724\uACFD\uC744 \uB0A8\uAE41\uB2C8\uB2E4. \uD45C\uC2DC\uCC3D\uC774 OK\uAE4C\uC9C0 \uCE74\uC6B4\uD2B8\uD55C \uB4A4 \uD6A8\uACFC\uAC00 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4."
