    "desc": "\uC601\uC6C5\uC758 \uC724\uACFD\uC774 \uAE5C\uBE61\uC774\uBA70 \uB098\uD0C0\uB09C \uB4A4 \uBAB8\uC774 \uD558\uC597\uAC8C \uBC88\uCA4D\uC774\uACE0 \uBA38\uB9AC\uBD80\uD130 \uBE5B\uC73C\uB85C \uBD84\uD574\uB429\uB2C8\uB2E4. \uBE5B\uC740 \uBC14\uB2E5\uC5D0\uC11C \uB5A0\uC62C\uB77C \uAC00\uB298\uAC8C \uB2EB\uD788\uB294 \uAD11\uC120\uC744 \uB530\uB77C \uC62C\uB77C\uAC11\uB2C8\uB2E4."
