    "desc": "\uBB34\uAC81\uACE0 \uBD80\uB4DC\uB7EC\uC6B4 \uD0C0\uACA9\uC785\uB2C8\uB2E4. \uB530\uB73B\uD55C \uBE5B \uC18D\uC5D0\uC11C \uD558\uC597\uAC8C \uB2EC\uC544\uC624\uB978 \uC6B8\uD241\uBD88\uD241\uD55C \uB369\uC5B4\uB9AC\uAC00 \uD06C\uB9BC\uC0C9\uC73C\uB85C \uC2DD\uACE0, \uAC80\uC740 \uD14C\uB450\uB9AC\uC758 \uC410\uAE30\uB4E4\uC774 \uD280\uC5B4\uB098\uC654\uB2E4 \uB418\uB3CC\uC544\uAC11\uB2C8\uB2E4. \uB0A9\uC791\uD55C \uBA3C\uC9C0 \uACE0\uB9AC\uAC00 \uBD80\uD480\uC5B4 \uD769\uC5B4\uC9C0\uACE0 \uD759\uB369\uC774\uAC00 \uB5A8\uC5B4\uC9D1\uB2C8\uB2E4."
