    "desc": "\uCE90\uB9AD\uD130\uAC00 \uD53C\uD574\uB97C \uBC1B\uC2B5\uB2C8\uB2E4. \uD55C \uD504\uB808\uC784 \uB3D9\uC548 \uD558\uC597\uAC8C \uBCC0\uD55C \uB4A4 \uC6D0\uB798 \uC0C9\uC774 \uBD89\uAC8C \uBB3C\uB4E4\uACE0 \uD770\uC0C9\uC73C\uB85C \uAE5C\uBC15\uC774\uBA70 \uC11C\uC11C\uD788 \uC2DD\uC2B5\uB2C8\uB2E4. \uB3D9\uC2DC\uC5D0 \uB9CC\uD654\uD48D \uD0C0\uACA9\uC120\uC774 \uCE90\uB9AD\uD130\uB97C \uD5A5\uD574 \uCC0C\uB985\uB2C8\uB2E4."
