    "desc": "\uB450 \uCE7C\uB0A0\uC774 \uBD80\uB52A\uD600 X\uC790\uB85C \uBC88\uCA4D\uC774\uACE0 \uD558\uC580 \uB124 \uAC08\uB798 \uBCC4\uC774 \uD37C\uC9D1\uB2C8\uB2E4. \uACE0\uB9AC\uB294 \uC5EC\uB7EC \uD638\uB85C \uBD80\uC11C\uC9C0\uACE0 \uD669\uAE08\uBE5B \uBD88\uAF43\uC774 \uBD80\uCC44\uAF34\uB85C \uC19F\uC544\uC62C\uB790\uB2E4 \uC3DF\uC544\uC9D1\uB2C8\uB2E4."
