    "desc": "\uC587\uC740 \uB0A0\uAC1C\uAC00 \uC606\uBA74\uC73C\uB85C \uBE5B\uC744 \uBC1B\uB2E4\uAC00 \uC704\uC5D0\uC11C \uC544\uB798\uB85C \uAE30\uC6B8\uC5B4 \uB2EB\uD799\uB2C8\uB2E4. \uBE5B\uB098\uB294 \uAC00\uC7A5\uC790\uB9AC\uAC00 \uBC18\uC9DD\uC774\uACE0 \uB2EB\uD788\uB294 \uD2C8 \uC0AC\uC774\uB85C \uB530\uB73B\uD55C \uBE5B\uACFC \uBA3C\uC9C0\uAC00 \uBE44\uCE5C \uB4A4, \uB0A0\uAC1C\uAC00 \uB2E4\uC2DC \uC5F4\uB9AC\uBA70 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4."
